window.bookSummaryJSON = "<p>Book 2 in this action-packed new Apocalypse LitRPG Adventure from best-selling author J Pal. Featuring a unique System that fuses LitRPG, Cultivation, and super powers along with gladiator fights, battle royales, and other combat games where death is always a possibility.<br> <br> It's perfect for fans of <i>Solo Leveling</i>, <i>Super Supportive,</i> and <i>Iron Prince!</i></p>"; 
